// Native GDI+ replay of byte-exact property aliases; no TurtleGit code linked.
#define wmain OriginalInterpolationReferenceMain
#include "InterpolationReference.cpp"
#undef wmain
static Bytes loadWire(const fs::path& p){std::ifstream f(p,std::ios::binary);Bytes b((std::istreambuf_iterator<char>(f)),{});if(b.size()>65536)throw std::runtime_error("wire budget");return b;}
static int patch(Bytes& b,int mode){int changed=0;for(size_t p=0;p+8<=b.size();){DWORD type=u32(b,p),size=u32(b,p+4);if(size<8||size>b.size()-p)throw std::runtime_error("EMF bounds");if(type==70&&size>=16&&u32(b,p+12)==0x2b464d45){size_t end=p+12+u32(b,p+8);for(size_t q=p+16;q+12<=end;){DWORD n=u32(b,q+4);if(n<12||n>end-q)throw std::runtime_error("EMF+ bounds");if(u16(b,q)==0x4021){if((u16(b,q+2)&255)!=5)throw std::runtime_error("not native nearest");b[q+2]=BYTE(mode);changed++;}q+=n;}}p+=size;}if(changed!=1)throw std::runtime_error("exactly one native interpolation property expected");return changed;}
int wmain(int argc,wchar_t** argv){try{if(argc!=3)throw std::runtime_error("input and output required");GdiplusStartupInput input;ULONG_PTR token=0;ok(GdiplusStartup(&token,&input,nullptr),"startup");{fs::path source(argv[1]),out(argv[2]);fs::create_directories(out);std::ofstream report(out/"wire-variant-observations.json");report<<"{\"schema\":1,\"cases\":[";bool first=true;int count=0;for(bool alpha:{false,true})for(int pixel:{0,3,4})for(const char* scene:{"integer","quarter","half","three-quarter","negative","reflection","affine","crop"})for(int mode:{0,1,3,5}){auto name=std::string(alpha?"alpha":"opaque")+"-i5-p"+std::to_string(pixel)+"-"+scene;auto bytes=loadWire(source/(name+".emf"));auto original=bytes;int changed=patch(bytes,mode);auto id=name+"-wire"+std::to_string(mode);write(out/(id+".emf"),bytes);records(out/(id+".emf"),out/(id+"-records.json"));write(out/(id+"-natural.rgba"),replay(out/(id+".emf"),false));write(out/(id+"-picture.rgba"),replay(out/(id+".emf"),true));if(!first)report<<",";first=false;int diff=0;for(size_t i=0;i<bytes.size();i++)if(bytes[i]!=original[i])diff++;report<<"{\"name\":\""<<id<<"\",\"source\":\""<<name<<"\",\"mode\":"<<mode<<",\"propertyCount\":"<<changed<<",\"changedBytes\":"<<diff<<"}";count++;}report<<"],\"completedCaseCount\":"<<count<<"}";std::cout<<"Captured "<<count<<" raw interpolation aliases\n";}GdiplusShutdown(token);return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
